/**
 * Pure helpers for resizable grid columns (no React, so node:test can load them).
 *
 * A column's width lives in the CSS variable `--grid-col-<key>` on the grid root;
 * the markup uses `var(--grid-col-<key>, <default>px)` in its grid template.
 */

export const MIN_WIDTH = 120;
export const MAX_WIDTH = 900;

export function columnVar(key) {
  return `--grid-col-${key}`;
}

export function clampWidth(width, min = MIN_WIDTH, max = MAX_WIDTH) {
  return Math.round(Math.min(max, Math.max(min, width)));
}

/** Stored widths by column key; anything unreadable counts as none. */
export function loadWidths(storage, storageKey) {
  if (!storageKey) return {};
  try {
    const data = JSON.parse(storage.getItem(storageKey) || "{}");
    if (!data || typeof data !== "object" || Array.isArray(data)) return {};
    return Object.fromEntries(
      Object.entries(data).filter(([, width]) => Number.isFinite(width)),
    );
  } catch {
    return {};
  }
}

export function saveWidths(storage, storageKey, widths) {
  if (!storageKey) return;
  try {
    storage.setItem(storageKey, JSON.stringify(widths));
  } catch {
    // Private mode or full storage: the widths last for this page only.
  }
}

import assert from "node:assert/strict";
import { describe, it } from "node:test";

import {
  MAX_WIDTH,
  MIN_WIDTH,
  clampWidth,
  columnVar,
  loadWidths,
  saveWidths,
} from "../../src/alloq_commons/components/excel_grid/column_widths.js";

function memoryStorage(initial = {}) {
  const data = { ...initial };
  return {
    data,
    getItem: (key) => (key in data ? data[key] : null),
    setItem: (key, value) => {
      data[key] = value;
    },
  };
}

describe("column widths", () => {
  it("names the CSS variable after the column key", () => {
    assert.equal(columnVar("12"), "--grid-col-12");
  });

  it("keeps a width between the limits and rounds it", () => {
    assert.equal(clampWidth(10), MIN_WIDTH);
    assert.equal(clampWidth(5000), MAX_WIDTH);
    assert.equal(clampWidth(240.6), 241);
    assert.equal(clampWidth(90, 80, 100), 90);
  });

  it("loads stored widths and ignores broken data", () => {
    const storage = memoryStorage({
      good: JSON.stringify({ a: 200, b: "wide" }),
      list: "[1,2]",
      broken: "{",
    });
    assert.deepEqual(loadWidths(storage, "good"), { a: 200 });
    assert.deepEqual(loadWidths(storage, "list"), {});
    assert.deepEqual(loadWidths(storage, "broken"), {});
    assert.deepEqual(loadWidths(storage, "missing"), {});
    assert.deepEqual(loadWidths(storage, ""), {});
  });

  it("saves widths and survives a failing storage", () => {
    const storage = memoryStorage();
    saveWidths(storage, "k", { a: 300 });
    assert.equal(storage.data.k, '{"a":300}');
    saveWidths(storage, "", { a: 1 });
    assert.deepEqual(Object.keys(storage.data), ["k"]);
    const failing = {
      setItem: () => {
        throw new Error("full");
      },
    };
    assert.doesNotThrow(() => saveWidths(failing, "k", {}));
  });
});

/**
 * Resizable grid columns: dragging a `data-col-resize="<key>"` handle inside the
 * root sets `--grid-col-<key>` on the root. Widths are kept per viewer in
 * localStorage under `storageKey`; a double click on a handle resets the column.
 * Without a storage key the hook does nothing.
 */
import { useEffect } from "react";
import { clampWidth, columnVar, loadWidths, saveWidths } from "./column_widths.js";

export function useColumnResize(rootRef, storageKey) {
  useEffect(() => {
    const root = rootRef.current;
    if (!root || !storageKey) return undefined;
    const storage = window.localStorage;
    const widths = loadWidths(storage, storageKey);
    const apply = (col, width) => root.style.setProperty(columnVar(col), `${width}px`);
    Object.entries(widths).forEach(([col, width]) => apply(col, width));

    const handleOf = (e) => {
      const handle = e.target.closest?.("[data-col-resize]");
      return handle && root.contains(handle) ? handle : null;
    };

    const onPointerDown = (e) => {
      const handle = handleOf(e);
      if (!handle || e.button !== 0) return;
      e.preventDefault();
      const col = handle.getAttribute("data-col-resize");
      const startX = e.clientX;
      const startWidth = handle.parentElement.getBoundingClientRect().width;
      document.body.style.cursor = "col-resize";
      const move = (ev) => {
        widths[col] = clampWidth(startWidth + ev.clientX - startX);
        apply(col, widths[col]);
      };
      const up = () => {
        document.removeEventListener("pointermove", move);
        document.removeEventListener("pointerup", up);
        document.body.style.cursor = "";
        saveWidths(storage, storageKey, widths);
      };
      document.addEventListener("pointermove", move);
      document.addEventListener("pointerup", up);
    };

    const onDoubleClick = (e) => {
      const handle = handleOf(e);
      if (!handle) return;
      const col = handle.getAttribute("data-col-resize");
      delete widths[col];
      root.style.removeProperty(columnVar(col));
      saveWidths(storage, storageKey, widths);
    };

    root.addEventListener("pointerdown", onPointerDown);
    root.addEventListener("dblclick", onDoubleClick);
    return () => {
      root.removeEventListener("pointerdown", onPointerDown);
      root.removeEventListener("dblclick", onDoubleClick);
      Object.keys(widths).forEach((col) => root.style.removeProperty(columnVar(col)));
    };
  }, [rootRef, storageKey]);
}

/**
 * Resizable columns for grids that are not an ExcelGrid (ExcelGrid takes
 * `resizeKey` itself). Renders a plain div that owns the column width variables.
 */
import React, { useRef } from "react";
import { useColumnResize } from "./column_resize.js";

export function ColumnResize({ id, className, storageKey, children }) {
  const rootRef = useRef(null);
  useColumnResize(rootRef, storageKey);
  return (
    <div id={id} ref={rootRef} className={className}>
      {children}
    </div>
  );
}

